INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES
('bible-tea', 'season', 's-genesis', 'es', 'name', 'Génesis'),
('bible-tea', 'season', 's-genesis', 'es', 'description', 'Donde todo comenzó. La creación, los primeros humanos, inundaciones épicas y drama familiar que deja en ridículo a los reality shows.'),
('bible-tea', 'season', 's-exodus', 'es', 'name', 'Éxodo'),
('bible-tea', 'season', 's-exodus', 'es', 'description', 'La gran escapada. Esclavitud, plagas, mares abriéndose y el viaje original que duró 40 años.'),
('bible-tea', 'season', 's-leviticus', 'es', 'name', 'Levítico y Leyes'),
('bible-tea', 'season', 's-leviticus', 'es', 'description', 'El libro de reglas que nadie esperaba que fuera tan intenso — sacrificios, leyes de pureza, fiestas sagradas y lo que realmente significaba ser santo en el antiguo Israel.'),
('bible-tea', 'season', 's-numbers', 'es', 'name', 'Números'),
('bible-tea', 'season', 's-numbers', 'es', 'description', '40 años vagando, quejándose y aprendiendo a confiar en Dios. El viaje definitivo que salió mal.'),
('bible-tea', 'season', 's-deuteronomy', 'es', 'name', 'Deuteronomio'),
('bible-tea', 'season', 's-deuteronomy', 'es', 'description', 'Los discursos de despedida de Moisés. Un recordatorio de todo lo que Dios hizo y todo lo que Israel necesita hacer después.'),
('bible-tea', 'season', 's-joshua', 'es', 'name', 'Josué'),
('bible-tea', 'season', 's-joshua', 'es', 'description', 'La conquista de la Tierra Prometida. Muros caen, ciudades arden e Israel finalmente llega a casa.'),
('bible-tea', 'season', 's-judges', 'es', 'name', 'Jueces'),
('bible-tea', 'season', 's-judges', 'es', 'description', 'La era más oscura de Israel. Héroes surgen, el caos reina y todos hacen lo que quieren.'),
('bible-tea', 'season', 's-ruth', 'es', 'name', 'Rut'),
('bible-tea', 'season', 's-ruth', 'es', 'description', 'Una historia de amor de lealtad y redención ambientada en el período más oscuro de la historia de Israel.'),
('bible-tea', 'season', 's-1samuel', 'es', 'name', '1 Samuel'),
('bible-tea', 'season', 's-1samuel', 'es', 'description', 'Del último juez al primer rey. Samuel, Saúl y el ascenso de David.'),
('bible-tea', 'season', 's-2samuel', 'es', 'name', '2 Samuel'),
('bible-tea', 'season', 's-2samuel', 'es', 'description', 'El reinado de David — triunfos, tragedias y la familia más complicada de la Biblia.'),
('bible-tea', 'season', 's-1kings', 'es', 'name', '1 Reyes'),
('bible-tea', 'season', 's-1kings', 'es', 'description', 'La gloria de Salomón, el reino se divide y Elías se enfrenta a 450 profetas.'),
('bible-tea', 'season', 's-2kings', 'es', 'name', '2 Reyes'),
('bible-tea', 'season', 's-2kings', 'es', 'description', 'La larga decadencia. Buenos reyes, malos reyes y la caída de dos naciones.'),
('bible-tea', 'season', 's-2chronicles', 'es', 'name', '2 Crónicas'),
('bible-tea', 'season', 's-2chronicles', 'es', 'description', 'La historia del reino del sur contada de nuevo — reformadores, rebeldes y el camino al exilio.'),
('bible-tea', 'season', 's-daniel', 'es', 'name', 'Daniel'),
('bible-tea', 'season', 's-daniel', 'es', 'description', 'Fosos de leones, hornos ardientes y visiones apocalípticas. Fidelidad bajo presión.'),
('bible-tea', 'season', 's-esther', 'es', 'name', 'Ester'),
('bible-tea', 'season', 's-esther', 'es', 'description', 'Una reina de belleza salva a su pueblo. El nombre de Dios nunca se menciona, pero sus huellas están por todas partes.'),
('bible-tea', 'season', 's-jonah', 'es', 'name', 'Jonás'),
('bible-tea', 'season', 's-jonah', 'es', 'description', 'Un profeta huye de Dios, es tragado por un pez y aprende sobre la misericordia por las malas.'),
('bible-tea', 'season', 's-matthew', 'es', 'name', 'Mateo'),
('bible-tea', 'season', 's-matthew', 'es', 'description', 'El Evangelio escrito para lectores judíos. Jesús como el Mesías prometido, desde el nacimiento hasta la resurrección.'),
('bible-tea', 'season', 's-mark', 'es', 'name', 'Marcos'),
('bible-tea', 'season', 's-mark', 'es', 'description', 'El Evangelio de ritmo rápido. Milagros llenos de acción y el siervo sufriente.'),
('bible-tea', 'season', 's-luke', 'es', 'name', 'Lucas'),
('bible-tea', 'season', 's-luke', 'es', 'description', 'El Evangelio más detallado. Jesús como amigo de los marginados, pecadores y olvidados.'),
('bible-tea', 'season', 's-john', 'es', 'name', 'Juan'),
('bible-tea', 'season', 's-john', 'es', 'description', 'El Evangelio espiritual. Conversaciones profundas, señales y el Verbo hecho carne.'),
('bible-tea', 'season', 's-acts', 'es', 'name', 'Hechos'),
('bible-tea', 'season', 's-acts', 'es', 'description', 'La iglesia primitiva explota. Desde una habitación en Jerusalén hasta los confines del Imperio Romano.'),
('bible-tea', 'season', 's-james', 'es', 'name', 'Santiago'),
('bible-tea', 'season', 's-james', 'es', 'description', 'La fe sin obras está muerta. Sabiduría práctica para la vida cristiana real.'),
('bible-tea', 'season', 's-2peter', 'es', 'name', '2 Pedro'),
('bible-tea', 'season', 's-2peter', 'es', 'description', 'La urgente carta final de Pedro. Aférrate a la verdad, cuidado con los falsos.'),
('bible-tea', 'season', 's-2timothy', 'es', 'name', '2 Timoteo'),
('bible-tea', 'season', 's-2timothy', 'es', 'description', 'La última carta de Pablo desde la prisión. Un veterano pasa la antorcha a la siguiente generación.'),
('bible-tea', 'season', 's-revelation', 'es', 'name', 'Apocalipsis'),
('bible-tea', 'season', 's-revelation', 'es', 'description', 'El final definitivo. Visiones, bestias y el nuevo cielo y la nueva tierra.');
